import{_ as e,c as t,o as n,a4 as i}from"./chunks/framework.ttppV29E.js";const k=JSON.parse('{"title":"Connecting A2A Clients","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agents/connecting-clients.md","filePath":"docs/agents/connecting-clients.md","lastUpdated":1782376534000}'),a={name:"docs/agents/connecting-clients.md"},s=i(`<h1 id="connecting-a2a-clients" tabindex="-1">Connecting A2A Clients <a class="header-anchor" href="#connecting-a2a-clients" aria-label="Permalink to &quot;Connecting A2A Clients&quot;">​</a></h1><p>A2A clients connect to AireGlu agents over HTTP using the A2A protocol (JSON-RPC) with OAuth 2.0 authentication. AireGlu agents implement the A2A protocol via the official <a href="https://github.com/a2aproject/a2a-dotnet" target="_blank" rel="noreferrer">a2a-dotnet SDK</a> at protocol version 1.0.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><p>Every agent exposes two endpoints:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET  https://&lt;runtime-host&gt;/a2a/&lt;tenancy&gt;/&lt;agent-name&gt;/.well-known/agent.json</span></span>
<span class="line"><span>POST https://&lt;runtime-host&gt;/a2a/&lt;tenancy&gt;/&lt;agent-name&gt;</span></span></code></pre></div><p>The first is the public agent card discovery endpoint. The second is the authenticated JSON-RPC interface used for everything else.</p><p>Unlike MCP servers, the agent URL does not include a version segment. A2A clients consume the agent card to learn what version is currently being served, and the default version is selected automatically. To change which version is exposed, update the agent&#39;s <strong>Default Version</strong>.</p><h3 id="copying-the-connection-url" tabindex="-1">Copying the Connection URL <a class="header-anchor" href="#copying-the-connection-url" aria-label="Permalink to &quot;Copying the Connection URL&quot;">​</a></h3><ol><li>Navigate to <strong>AI Tools &gt; Agents</strong></li><li>Click the three-dot menu on the agent row</li><li>Select <strong>Copy URL</strong></li></ol><h2 id="agent-card-discovery" tabindex="-1">Agent Card Discovery <a class="header-anchor" href="#agent-card-discovery" aria-label="Permalink to &quot;Agent Card Discovery&quot;">​</a></h2><p>The agent card is the A2A protocol&#39;s public, unauthenticated discovery document. Calling agents fetch it first to learn what the agent does, what skills it advertises, and how to authenticate.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">runtime-hos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/a2a/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tenanc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">agent-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.well-known/agent.json</span></span></code></pre></div><p>The card returned by AireGlu includes:</p><ul><li><code>name</code> and <code>description</code> from the agent configuration</li><li><code>version</code> of the currently-default version</li><li><code>skills</code> advertised by that version</li><li><code>defaultInputModes</code> and <code>defaultOutputModes</code></li><li><code>capabilities</code> — streaming is supported; push notifications are not</li><li><code>securitySchemes</code> — OpenID Connect against the AireIdentity authority</li><li><code>securityRequirements</code> — the <code>AireGluAgent</code> scope</li><li><code>supportedInterfaces</code> — a single JSON-RPC binding pointing at the agent endpoint</li></ul><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>A2A clients obtain a JWT token from the OpenID Connect provider advertised in the agent card and pass it as a Bearer token on every JSON-RPC request.</p><p>The required OAuth scope is <code>AireGluAgent</code>. The user (or service principal) authenticated by the token must hold the <code>run:Agent</code> permission for the request to be authorised.</p><ol><li>The client fetches OpenID Connect metadata from the URL in the agent card</li><li>The client obtains a token via OAuth 2.0 (typically authorization code or client credentials, depending on the client)</li><li>The token is included as a Bearer token in subsequent JSON-RPC requests</li><li>AireGlu validates the token, checks for <code>run:Agent</code>, and resolves the tenant</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table><thead><tr><th>Issue</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>404 on agent card</td><td>Agent or its default version is inactive, or no default is set</td><td>Check the Active toggle on both the agent and its versions; confirm a default version is set</td></tr><tr><td>401 Unauthorized</td><td>Invalid or expired token, or missing <code>run:Agent</code> permission</td><td>Re-authenticate; confirm your account has the <code>run:Agent</code> claim</td></tr><tr><td>Token tenant mismatch</td><td>Token was issued to a different tenant than the URL</td><td>Use a token issued to the same tenant the agent belongs to</td></tr><tr><td>405 Method Not Allowed on agent endpoint</td><td>Client called something other than POST</td><td>A2A JSON-RPC uses POST only</td></tr><tr><td>No tools available to the agent</td><td>No MCP servers configured, or referenced servers are missing</td><td>Edit the agent version and add or fix MCP server references</td></tr></tbody></table>`,20),o=[s];function r(d,l,h,c,p,g){return n(),t("div",null,o)}const y=e(a,[["render",r]]);export{k as __pageData,y as default};
